#!/usr/bin/env node
/**
 * tred-bibliotheque-de-cours.mjs
 *
 * La bibliotheque de cours partagee : plusieurs etudiants d'une meme
 * Vorlesung voient les memes Skripte, Uebungen et Altklausuren.
 *
 *   /courses          rejoindre un cours, voir ce qu'il contient, y deposer
 *   portee du tuteur  mes documents + ceux partages dans mes cours
 *   retrait           immediat et total, pour tout le monde
 *
 * Corrige aussi un defaut plus ancien : cette i18n maison interpole {cle} et
 * non {{cle}}. Six textes ecrits avec des accolades doubles n'ont jamais
 * affiche leur valeur — ils montraient « {Analysis} ».
 *
 * Verifie ici : tsc 0, oxlint 0, bun test 141/141, vite build.
 *
 *   node tred-bibliotheque-de-cours.mjs
 *   node migre-cours.mjs               <- INDISPENSABLE, et a lancer AVANT
 */
import { writeFileSync, mkdirSync, existsSync, rmSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { inflateSync } from "node:zlib";

function racine() {
  const departs = [process.cwd(), dirname(fileURLToPath(import.meta.url))];
  for (const depart of departs) {
    let d = resolve(depart);
    for (let i = 0; i < 8; i++) {
      if (existsSync(join(d, "packages", "web", "package.json"))) return d;
      const parent = dirname(d);
      if (parent === d) break;
      d = parent;
    }
  }
  return null;
}

const R = racine();
if (!R) {
  console.error("Depot introuvable. Lance-le depuis C:\\dev\\tred-rdm\\aerostudy-ai.");
  process.exit(1);
}
console.log("Depot :", R, "\n");

const PAYLOAD = "";

const LOT = JSON.parse(inflateSync(Buffer.from(PAYLOAD, "base64")).toString("utf8"));
let n = 0;
for (const [chemin, b64] of Object.entries(LOT.ecrire)) {
  const cible = join(R, chemin);
  mkdirSync(dirname(cible), { recursive: true });
  writeFileSync(cible, Buffer.from(b64, "base64"));
  n++;
}
for (const chemin of LOT.supprimer) {
  const cible = join(R, chemin);
  if (existsSync(cible)) rmSync(cible);
}

console.log(`${n} fichiers poses.\n`);
console.log("1) La base d'abord — sans elle, /courses renvoie une erreur :");
console.log("     node migre-cours.mjs --voir     (montre ce qui manque)");
console.log("     node migre-cours.mjs            (applique)");
console.log("\n2) Puis l'envoi :");
console.log("     git add -A");
console.log("     git commit -m \"bibliotheque de cours partagee\"");
console.log("     git push");
